#include <Aevrynd/Camera.h>
#include <Aevrynd/Mesh3D.h>
#include <Aevrynd/Renderer.h>
#include <Windows.h>
#include <algorithm>
#include <chrono>
#include <iostream>
#include <vector>
using namespace Aevrynd;
struct Samples{uint64_t cpuMedian{},cpuP95{},gpuMedian{},gpuP95{};};
static uint64_t Percentile(std::vector<uint64_t> values,size_t numerator){std::ranges::sort(values);return values[(values.size()-1)*numerator/100];}
static Samples Measure(D3D12Renderer& renderer,const DrawList& draw,bool enabled){renderer.SetGpuInstanceCullingSettings({enabled,500.f});for(int frame=0;frame<12;++frame){renderer.Render(draw,{0,0,0,1});renderer.WaitIdle();}std::vector<uint64_t> cpu,gpu;for(int frame=0;frame<40;++frame){const auto begin=std::chrono::steady_clock::now();renderer.Render(draw,{0,0,0,1});const auto end=std::chrono::steady_clock::now();renderer.WaitIdle();cpu.push_back(uint64_t(std::chrono::duration_cast<std::chrono::nanoseconds>(end-begin).count()));gpu.push_back(renderer.GetStats().lastGpuFrameNanoseconds);}return{Percentile(cpu,50),Percentile(cpu,95),Percentile(gpu,50),Percentile(gpu,95)};}
int main(){HINSTANCE instance=GetModuleHandleW(nullptr);WNDCLASSW wc{};wc.lpfnWndProc=DefWindowProcW;wc.hInstance=instance;wc.lpszClassName=L"AevryndGpuCullingBenchmark";RegisterClassW(&wc);HWND window=CreateWindowW(wc.lpszClassName,L"GPU culling benchmark",WS_OVERLAPPED,0,0,1920,1080,nullptr,nullptr,instance,nullptr);if(!window)return 1;D3D12Renderer renderer;renderer.Initialize(window,1920,1080,1920,1080,false);renderer.SetQualitySettings({false,false,false,false});const Mesh3D sphere=Mesh3D::CreateUnitSphere(32,16);const auto mesh=renderer.CreateMesh(sphere.vertices,sphere.indices);Camera3D camera{{0,0,-12},{0,0,0},{0,1,0},{}};const Matrix4 view=CreateViewProjectionMatrix(camera,1920.f/1080.f);DrawList rejected;rejected.SetViewProjection(view);for(int index=0;index<4096;++index){const bool outside=index>=410;rejected.MeshInstance(mesh,CreateTranslationMatrix({outside?2000.f:float(index%20-10)*.3f,float((index/20)%20-10)*.3f,float(index%5)*.2f}));}DrawList ordinary;ordinary.SetViewProjection(view);for(int index=0;index<2048;++index)ordinary.MeshInstance(mesh,CreateTranslationMatrix({float(index%32-16)*.18f,float((index/32)%32-16)*.18f,float(index%4)*.2f}));const Samples rejectedDirect=Measure(renderer,rejected,false),rejectedIndirect=Measure(renderer,rejected,true),ordinaryDirect=Measure(renderer,ordinary,false),ordinaryIndirect=Measure(renderer,ordinary,true);const RendererStats ordinaryStats=renderer.GetStats();renderer.DestroyMesh(mesh);renderer.WaitIdle();DestroyWindow(window);const double rejectedGain=1.0-double(rejectedIndirect.gpuMedian)/double(rejectedDirect.gpuMedian),ordinaryRegression=double(ordinaryIndirect.gpuMedian)/double(ordinaryDirect.gpuMedian)-1.0;std::cout<<"rejected_direct_gpu_ns="<<rejectedDirect.gpuMedian<<" rejected_indirect_gpu_ns="<<rejectedIndirect.gpuMedian<<" rejected_gain="<<rejectedGain<<" ordinary_direct_gpu_ns="<<ordinaryDirect.gpuMedian<<" ordinary_indirect_gpu_ns="<<ordinaryIndirect.gpuMedian<<" ordinary_regression="<<ordinaryRegression<<" rejected_cpu_median="<<rejectedIndirect.cpuMedian<<" rejected_cpu_p95="<<rejectedIndirect.cpuP95<<" rejected_gpu_p95="<<rejectedIndirect.gpuP95<<" ordinary_gpu_p95="<<ordinaryIndirect.gpuP95<<'\n';return rejectedGain>=.20&&ordinaryRegression<=.05&&ordinaryStats.lastGpuInstanceCullingCandidates==2048&&ordinaryStats.gpuInstanceIndirectDraws?0:2;}
